import{_ as t,o as i,a as e,b as s}from"./app.C41L12d5.js";const o="/ascendc.github.io/assets/op_csv_ex1.BLv_XC1X.png",r="/ascendc.github.io/assets/op_csv_ex2.DqQdCr8x.png",l="/ascendc.github.io/assets/op_csv_ex.gR2QBhR1.png",p="/ascendc.github.io/assets/sim_pipe_ex.BmqTCDpk.png",f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"性能分析","link":"/guide/operator_practice/performance_analysis/performance_analysis"},{"text":"分析性能数据","link":"/guide/operator_practice/performance_analysis/analyze_performance_data"}]},"headers":[],"relativePath":"guide/operator_practice/performance_analysis/analyze_performance_data.md","filePath":"guide/operator_practice/performance_analysis/analyze_performance_data.md","outlineHeaders":[{"level":2,"title":"理论参数","slug":"理论参数","link":"#理论参数"},{"level":2,"title":"查找瓶颈","slug":"查找瓶颈","link":"#查找瓶颈"}],"lastUpdated":1787050286000}'),n={name:"guide/operator_practice/performance_analysis/analyze_performance_data.md"};function _(c,a,m,g,d,h){return i(),e("div",null,[...a[0]||(a[0]=[s('<div><article class="markdown-body"><h1>分析性能数据<span id="ZH-CN_TOPIC_0000001846719828"></span></h1><h2 id="理论参数">理论参数<span id="section142521157183920"></span><a class="header-anchor" href="#理论参数">​</a></h2><p>理论性能为算子实际性能的理想目标。不同的硬件平台的硬件规格各异，理论性能可以帮助我们了解硬件的潜能，从而设定性能优化的目标。</p><ul><li><p>搬运相关流水（MTE1/MTE2/MTE3等）的理论耗时 = 搬运数据量（单位：Byte） / 理论带宽。例如：某款AI处理器的GM峰值带宽约为1.8TB/s，想要进行一次float数据类型、4096 * 4096大小的矩阵搬运，搬运的理论耗时是sizeof(float) * 4096 * 4096 / 1.8TB/s = 37.28us（按照1TB =10<sup>12</sup>Byte来计算）。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>搬运指令同时存在时，会存在共享带宽的情况，并不能每条都以接近理论带宽的速率搬运数据。比如，当MTE2/MTE3同时进行GM读写时，搬运流水线的耗时应该是（MTE2搬运量 + MTE3搬运量）/ GM带宽。</li><li>搬运不同大小的数据块时，对带宽的利用率（有效带宽/理论带宽）不一样。针对每次搬运数据量较小的情况，实测性能达不到理论带宽。</li></ul></div></li><li><p>计算相关流水（Cube/Vector/Scalar等）的理论耗时 = 计算数据量（单位：Element） / 理论算力。例如：某款AI处理器对float数据类型的Vector理论峰值算力为11.06TOPS，想要进行一次32K float类型的Element单指令计算，计算的理论耗时是32K / 11.06TOPS = 0.003us （按照1K =1000来计算）。</p></li></ul><h2 id="查找瓶颈">查找瓶颈<span id="section423433354011"></span><a class="header-anchor" href="#查找瓶颈">​</a></h2><p><a href="collect_performance_data.html">获取性能数据</a>后，和理论数值差异较大的地方、耗时较长的流程被认为是“<strong>瓶颈点</strong>”。下文将介绍如何通过性能数据找到瓶颈点和对应的优化方向。</p><ul><li><p><strong>方法一：通过上板Profiling分析流水情况</strong></p><p>查看上板Profiling解析后的op_summary_*.csv文件分析流水情况。注：“*”表示时间戳。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>在SIMD与SIMT混合编程场景中，由于硬件架构的固有特性，所有计算任务均以VF（Vector Function）为基本调度执行单元。因此，在Profiling数据中，SIMT和SIMD的VF整体执行时间均被统计为aiv_vec_time。特别地，SIMT VF执行过程中对Global Memory的读写耗时，也会被统计至aic_vec_time指标内。</p></div><p><strong>图1</strong> op_summary_*.csv示例一<span id="fig15532143763010"></span><br><img src="'+o+'" alt title="op_summary_-csv示例一"></p><p>每条流水线的利用率理想情况下应为100%，没有达到100%的流水就可能有提升空间。上图示例中为某款AI处理器上获取的数据，可以看到Cube算子MatMulV2，Cube流水的利用率aic_mac_ratio在80%左右，初步判断没有充分发挥算力；MTE2流水的利用率aic_mte2_ratio已经在95%左右，判断MTE2是最长的流水。</p><p>然后比较最长的流水和理论的差距：输入左右矩阵的shape分别为（2048，12288）、（12288，6144），数据类型为bfloat16；Bias输入的shape为（6144），数据类型为float。由此可以计算出总共需要搬运的数据量，继而通过<a href="#section142521157183920">理论参数</a>中介绍的搬运流水理论耗时计算方法计算出理论值为(sizeof(bfloat16) * (2048 * 12288 + 12288 * 6144) + sizeof(float) * 6144) / 1.8TB/s ≈ 111.8us （按照1TB =10<sup>12</sup>Byte来计算），与实际性能数据aic_mte2_time存在比较大的差距。经分析输入数据的总大小已经超过L1的空间（512KB），做MatMul计算会存在输入矩阵数据重复搬运的情况，重复搬运的次数是否合理，需要结合<a href="../simd_operator_optimization/pipeline_scheduling/pipeline_scheduling.html">流水优化</a>和<a href="../simd_operator_optimization/tiling_strategy/tiling_strategy.html">Tiling优化</a>手段进行优化，可参考<a href="#li169522115204">方法三、查看仿真流水图分析各条流水的情况</a>进一步分析。</p><p><strong>图2</strong> op_summary_*.csv示例二<span id="fig115151013124114"></span><br><img src="'+r+'" alt title="op_summary_-csv示例二"></p><p>上图示例中算子输入的shape为（8192，8192），数据类型为float。由此可以计算出总共需要搬运的数据量，继而通过<a href="#section142521157183920">理论参数</a>中介绍的搬运流水理论耗时计算方法计算出理论值为sizeof(float) * (8192 * 8192) / 0.8TB/s ≈ 335.5us （按照1TB =10<sup>12</sup>Byte来计算，不同的AI处理器其理论带宽有差异），与实际性能数据aiv_mte2_time相符，可以判断该算子基本是一个搬运MTE2 bound（达到上限）的算子。本示例中总体执行时间Duration为350us，和MTE2的实际耗时持平，说明该算子已经调优完成。如果MTE2耗时和总体执行时间有较大差距，那么下一步优化方向主要是<a href="../simd_operator_optimization/pipeline_scheduling/pipeline_scheduling.html">流水优化</a>结合<a href="../simd_operator_optimization/tiling_strategy/tiling_strategy.html">Tiling优化</a>，使得其他的流水尽量隐藏在MTE2的流水中，可参考<a href="#li169522115204">方法三、查看仿真流水图分析各条流水的情况</a>进行进一步分析。</p></li><li><p><strong>方法二：通过上板Profiling分析Tiling情况</strong></p><p>查看上板Profiling解析后的op_summary_*.csv文件分析Tiling情况。</p><p><strong>图3</strong> op_summary_*.csv示例<span id="fig10442174973013"></span><br><img src="'+l+'" alt title="op_summary_-csv示例"></p><p>上图示例中为某款AI处理器上获取的数据，通过硬件平台可以查看该AI处理器有48个Vector核，Mul算子是一个纯Vector算子，但是有些场景没有用满所有Vector核（Block Dim &lt; 48），造成算力浪费。那么下一步的主要优化方向为<a href="../simd_operator_optimization/tiling_strategy/tiling_strategy.html">Tiling优化</a>。</p></li><li><p><span id="li169522115204"></span><strong>方法三：通过仿真流水图分析流水情况</strong></p><p><strong>图4</strong> 仿真流水图示例<span id="fig1978415320315"></span><br><img src="'+p+'" alt title="仿真流水图示例"></p><p>上图示例中为某款AI处理器上获取的数据，可以看到Vector核的相关流水（vec0的MTE2、MTE3，vec1的MTE2、MTE3等）有规律性的断流现象。可以结合算子逻辑分析，是否存在数据依赖等因素导致断流。那么下一步的主要优化方向为<a href="../simd_operator_optimization/pipeline_scheduling/enable_double_buffer.html">流水优化</a>，其次结合<a href="../simd_operator_optimization/tiling_strategy/tiling_strategy.html">Tiling优化</a>和<a href="../simd_operator_optimization/memory_access/memory_access.html">内存优化</a>等手段进一步提升Vector流水利用率。</p></li><li><p><strong>方法四：通过上板Profiling查看头开销</strong></p><p>头开销是算子执行计算前产生的时延，包含核启动、核取址TLB MISS、同地址访问（由于硬件限制，多核同时访问相同内存地址冲突带来额外的时延）以及变量资源初始化带来的时延。以Atlas A2 训练系列产品/Atlas A2 推理系列产品为例，满核头开销约为20~21微秒。对于推理领域等本身延迟为微秒级别的算子，头开销是一个值得优化的对象。</p><p>通过<strong>上板Profiling</strong>数据（空核函数（Kernel）时的TaskDuration数据）可以看到每个核的启动开销耗时，继而通过<strong>使用恰当的核数和算子Kernel Type</strong>等方法来不断的实践，尝试找到最优的配置，具体优化方向可以参考<a href="../simd_operator_optimization/overhead_optimization/overhead_optimization.html">头尾开销优化</a>。</p></li></ul></article></div>',1)])])}const T=t(n,[["render",_]]);export{f as __pageData,T as default};
